# import necessary packages
from collections import deque
import random

# all class and function definitions in the code file, if any
class CallCenter:
    def __init__(self):
        self.respondents = deque()
        self.managers = deque()
        self.directors = deque()
        self.calls = []
        self.calling = {}

    def register_employee(self, employee_type="Respondent"):
        if employee_type == "Respondent":
            self.respondents.appendleft(Respondent())
        elif employee_type == "Manager":
            self.managers.appendleft(Manager())
        elif employee_type == "Director":
            self.directors.appendleft(Director())

    def dispatch_call(self, level):
        call = Call(len(self.calls), level)
        call_id = call.id
        if call.level == 1:
            if len(self.respondents) > 0:
                r = self.respondents.pop()
                self.calling[call_id] = r
                r.assign()
            elif len(self.managers) > 0:
                m = self.managers.pop()
                self.calling[call_id] = m
                m.assign()
            elif len(self.directors) > 0:
                d = self.directors.pop()
                self.calling[call_id] = d
                d.assign()
            else:
                return None
        elif call.level == 2:
            if len(self.managers) > 0:
                m = self.managers.pop()
                self.calling[call_id] = m
                m.assign()
            elif len(self.directors) > 0:
                d = self.directors.pop()
                self.calling[call_id] = d
                d.assign()
            else:
                return None
        elif call.level == 3:
            if len(self.directors) > 0:
                d = self.directors.pop()
                self.calling[call_id] = d
                d.assign()
            else:
                return None
        else:
            return None
        self.calls.append(call)
        return call_id

    def release_call(self, call_id):
        e = self.calling[call_id]
        e.release()
        if isinstance(e, Director):
            self.directors.appendleft(e)
        elif isinstance(e, Manager):
            self.managers.appendleft(e)
        elif isinstance(e, Respondent):
            self.respondents.appendleft(e)

class Call:
    def __init__(self, id, level=1):
        self.id = id
        self.level = level

class Employee:
    def __init__(self):
        self.free = True

    def assign(self):
        self.free = False

    def release(self):
        self.free = True

class Respondent(Employee):
    def __init__(self):
        super().__init__()
        self.level = 1

class Manager(Employee):
    def __init__(self):
        super().__init__()
        self.level = 2

class Director(Employee):
    def __init__(self):
        super().__init__()
        self.level = 3

# main function
def main_solution(num_respondents, num_managers, num_directors, call_level):
    # Initialize the call center
    center = CallCenter()

    # Register employees
    for _ in range(num_respondents):
        center.register_employee("Respondent")
    for _ in range(num_managers):
        center.register_employee("Manager")
    for _ in range(num_directors):
        center.register_employee("Director")

    # Dispatch a call
    call_id = center.dispatch_call(call_level)

    # Return the call ID or None if no employee is available
    return call_id

