# import necessary packages
import random

# all class and function definitions in the code file, if any
def mapcolor(c):
    if c == 'r':
        return 0
    elif c == 'g':
        return 1
    elif c == 'b':
        return 2

def findarea(mat, r, c, top, bottom, left, right):
    ans = 1
    for i in range(c):
        for x in range(3):
            for y in range(3):
                z = 3 - x - y
                if x != y and top[x][i] != float('inf') and bottom[y][i] != float('-inf') and left[z] != float('inf'):
                    ans = max(ans, 0.5 * (bottom[y][i] - top[x][i]) * (i - left[z]))
                if x != y and top[x][i] != float('inf') and bottom[y][i] != float('-inf') and right[z] != float('-inf'):
                    ans = max(ans, 0.5 * (bottom[y][i] - top[x][i]) * (right[z] - i))
    return ans

def maxarea(mat, r, c):
    left = [float('inf')] * 3
    right = [float('-inf')] * 3
    top = [[float('inf') for _ in range(c)] for _ in range(3)]
    bottom = [[float('-inf') for _ in range(c)] for _ in range(3)]

    for i in range(r):
        for j in range(c):
            left[mapcolor(mat[i][j])] = min(left[mapcolor(mat[i][j])], j)
            right[mapcolor(mat[i][j])] = max(right[mapcolor(mat[i][j])], j)

    for j in range(c):
        for i in range(r):
            top[mapcolor(mat[i][j])][j] = min(top[mapcolor(mat[i][j])][j], i)
            bottom[mapcolor(mat[i][j])][j] = max(bottom[mapcolor(mat[i][j])][j], i)

    return int(findarea(mat, r, c, top, bottom, left, right))

# main function
