    applied_tags_set = set(applied_tags.split(","))

    def get_requested_tags() -> Set[str]:
        return set(t for t in os.environ.get("TEST_TAGS", "").split(",") if not t.startswith("!") and t != "")

    def get_forbidden_tags() -> Set[str]:
